Lemma bit63_ge : forall x, 0 <= x < 2^64 -> (2^63 <= x <-> Z.testbit x 63 = true).
Proof.
  intros x Hx. rewrite Z.testbit_true by lia. split; intro H.
  - rewrite <- (Z.div_unique_pos x (2^63) 1 (x - 2^63)) by lia. reflexivity.
  - destruct (Z_lt_le_dec x (2^63)) as [L|L]; [|exact L]. rewrite Z.div_small in H by lia. discriminate.
Qed.

Lemma shl_land64_testbit : forall f s, 0 <= f -> 0 <= s <= 63 ->
  (9223372036854775808 <= Z.land (Z.shiftl f s) 18446744073709551615 <-> Z.testbit f (63 - s) = true).
Proof.
  intros f s Hf Hs.
  change 18446744073709551615 with (Z.ones 64). rewrite Z.land_ones by lia. change 9223372036854775808 with (2^63).
  rewrite bit63_ge by (apply Z.mod_pos_bound; lia).
  rewrite Z.mod_pow2_bits_low by lia. rewrite Z.shiftl_spec_high by lia. reflexivity.
Qed.

(* [comment removed for export] *)
Ltac cb_split H k H2 :=
  lazymatch type of H with rw_cells _ _ (?b + ?o) [CB ?n _] =>
    let nk := eval vm_compute in (n - k)%nat in
    let o2 := eval vm_compute in (o + Z.of_nat k) in
    let H1 := fresh "CBL" in
    destruct (rw_cells_CB_split usegs _ _ n k _ H ltac:(lia)) as [H1 H2]; clear H; rename H1 into H;
    change (n - k)%nat with nk in H2;
    replace (b + o + Z.of_nat k) with (b + o2) in H2 by lia
  end.

