Lemma dof_pure_st : forall sp P E lo c fld vp vbs,
  dof_pure sp P E lo c fld vp vbs -> dof_pure sp P E lo c (pc_state c) vp vbs.
Proof.
  intros sp P E lo c fld vp vbs (PCOK & FLD & REST). pose proof PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff).
  split; [exact PCOK|]. split; [|exact REST]. cbn in Stt. lia.
Qed.

Lemma tok_suffix_end : forall vp vbs, tok_suffix vp (vp + Z.of_nat (length vbs)) vbs = [].
Proof.
  intros vp vbs. unfold tok_suffix. replace (Z.to_nat (vp + Z.of_nat (length vbs) - vp)) with (length vbs) by lia.
  rewrite skipn_all. reflexivity.
Qed.

