Local Ltac call_ctor A Fi La W wbs cs lo :=
  let S := fresh "CS" in
  pose proof tokit_ctor_spec as S;
  unfold tokit_ctor_stmt, tokit_ctor_post, SZ_TOKIT, TOKIT_STACK, P_TOKEN_LIST_ITER_CTOR in S; unfold wz in S;
  callZ (S A Fi La W wbs cs lo);
  [ fast_assumption | first [reflexivity | fast_assumption] | fast_assumption | lia | lia | lia | lia
  | rewrite ?unsigned_lit by lia; fast_assumption | rewrite ?unsigned_lit by lia; lia | lia
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; lia
  | intros; lia | fast_assumption | clear S ].

Local Ltac call_incr A vp vl it fst La W wbs lo :=
